38	import org.springframework.samples.petclinic.service.ClinicService;
39	import org.springframework.samples.petclinic.service.OwnerAuditPolicy;
40	import org.springframework.samples.petclinic.service.OwnerCityCapacityPolicy;
41	import org.springframework.samples.petclinic.service.OwnerCustomerCodePolicy;
42	import org.springframework.samples.petclinic.service.OwnerDailyLimitPolicy;
43	import org.springframework.samples.petclinic.service.OwnerHouseholdPolicy;
44	import org.springframework.samples.petclinic.service.OwnerNamesakePolicy;
45	import org.springframework.samples.petclinic.service.OwnerRegistrationDatePolicy;
46	import org.springframework.samples.petclinic.service.OwnerTelephonePolicy;
