50	import org.springframework.web.bind.annotation.RestController;
51	import org.springframework.web.util.UriComponentsBuilder;
52	
53	import jakarta.transaction.Transactional;
54	
55	/**
56	 * @author Vitaliy Fedoriv
57	 */
58	
59	@RestController
60	@CrossOrigin(exposedHeaders = "errors, content-type")
61	@RequestMapping("/api")
62	public class OwnerRestControllerV1 implements OwnersApi {
63	
64	    private final ClinicService clinicService;
65	
66	    private final OwnerMapper ownerMapper;
67	
68	    private final PetMapper petMapper;
69	
70	    private final VisitMapper visitMapper;
71	
72	    public OwnerRestControllerV1(ClinicService clinicService,
73	                                 OwnerMapper ownerMapper,
74	                                 PetMapper petMapper,
75	                                 VisitMapper visitMapper) {
76	        this.clinicService = clinicService;
77	        this.ownerMapper = ownerMapper;
78	        this.petMapper = petMapper;
79	        this.visitMapper = visitMapper;
80	    }
81	
82	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
83	    @Override
84	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
85	        Collection<Owner> owners;
86	        if (lastName != null) {
87	            owners = this.clinicService.findOwnerByLastName(lastName);
88	        } else {
89	            owners = this.clinicService.findAllOwners();
90	        }
91	        if (owners.isEmpty()) {
92	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
93	        }
94	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
95	    }
96	
97	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
98	    @Override
99	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
100	        Owner owner = this.clinicService.findOwnerById(ownerId);
101	        if (owner == null) {
102	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
103	        }
104	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
105	    }
106	
107	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
108	    @Override
109	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
110	        HttpHeaders headers = new HttpHeaders();
111	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
112	        OwnerRegistrationDatePolicy.assignBusinessDayRegistrationDate(owner);
113	        OwnerDailyLimitPolicy.rejectWhenDailyLimitReached(this.clinicService, owner);
114	        OwnerCityCapacityPolicy.rejectWhenCityAtCapacity(this.clinicService, owner);
115	        OwnerHouseholdPolicy.rejectDuplicateHousehold(this.clinicService, owner, ownerFieldsDto.getSharesHousehold());
116	        OwnerTelephonePolicy.rejectDuplicateTelephone(this.clinicService, owner);
117	        OwnerNamesakePolicy.assignNamesakeCount(this.clinicService, owner);
118	        OwnerCustomerCodePolicy.assignCustomerCode(this.clinicService, owner);
119	        this.clinicService.saveOwner(owner);
120	        OwnerAuditPolicy.auditCreate(owner);
121	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
122	        headers.setLocation(UriComponentsBuilder.newInstance()
123	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
124	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
125	    }
126	
127	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
128	    @Override
129	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
130	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
131	        if (currentOwner == null) {
132	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
133	        }
134	        currentOwner.setAddress(ownerFieldsDto.getAddress());
135	        currentOwner.setCity(ownerFieldsDto.getCity());
136	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
137	        currentOwner.setLastName(ownerFieldsDto.getLastName());
138	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
139	        this.clinicService.saveOwner(currentOwner);
140	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
141	    }
142	
143	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
144	    @Transactional
145	    @Override
146	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
147	        Owner owner = this.clinicService.findOwnerById(ownerId);
148	        if (owner == null) {
149	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
150	        }
151	        this.clinicService.deleteOwner(owner);
152	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
153	    }
154	
155	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
156	    @Override
157	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
158	        Owner owner = this.clinicService.findOwnerById(ownerId);
159	        if (owner == null) {
160	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
161	        }
162	        HttpHeaders headers = new HttpHeaders();
163	        Pet pet = petMapper.toPet(petFieldsDto);
164	        owner.setId(ownerId);
165	        pet.setOwner(owner);
166	        pet.getType().setName(null);
167	        this.clinicService.savePet(pet);
168	        PetDto petDto = petMapper.toPetDto(pet);
169	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
170	            .buildAndExpand(pet.getId()).toUri());
171	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
172	    }
173	
174	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
175	    @Override
176	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
177	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
178	        if (currentOwner != null) {
179	            Pet currentPet = this.clinicService.findPetById(petId);
180	            if (currentPet != null) {
181	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
182	                currentPet.setName(petFieldsDto.getName());
183	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
184	                this.clinicService.savePet(currentPet);
185	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
186	            }
187	        }
188	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
189	    }
190	
191	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
192	    @Override
193	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
194	        HttpHeaders headers = new HttpHeaders();
195	        Visit visit = visitMapper.toVisit(visitFieldsDto);
196	        Pet pet = new Pet();
197	        pet.setId(petId);
198	        visit.setPet(pet);
199	        this.clinicService.saveVisit(visit);
200	        VisitDto visitDto = visitMapper.toVisitDto(visit);
201	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
202	            .buildAndExpand(visit.getId()).toUri());
203	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
204	    }
